require __DIR__.'/../bootstrap.php'; require_admin(); $msg=''; $c=ai_credentials(); $connectionType=(string)($c['auth_type']??'api_key'); if(!in_array($connectionType,['api_key','iam','relay'],true))$connectionType='api_key';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)post('action');if($action==='save'){$type=in_array((string)post('connection_type'),['api_key','iam','relay'],true)?(string)post('connection_type'):'api_key';set_setting('bedrock_auth_type',$type);set_setting('aws_region',trim((string)post('aws_region','us-east-1')));set_setting('bedrock_model_id',trim((string)post('bedrock_model_id','')));set_setting('bedrock_api_mode',$type==='iam'?'converse':'openai');set_setting('bedrock_transport',$type==='relay'?'relay':'direct');set_setting('bedrock_relay_url',$type==='relay'?rtrim(trim((string)post('bedrock_relay_url','')),'/'):'');set_setting('bedrock_endpoint_url',$type==='api_key'?rtrim(trim((string)post('bedrock_endpoint_url','')),'/'):'');if($type==='api_key'){foreach(['aws_access_key_id','aws_secret_access_key','aws_session_token','bedrock_relay_token'] as $k)set_setting($k,'');}elseif($type==='iam'){foreach(['bedrock_api_key','bedrock_relay_token'] as $k)set_setting($k,'');}else{foreach(['bedrock_api_key','aws_access_key_id','aws_secret_access_key','aws_session_token'] as $k)set_setting($k,'');}$activeSecrets=$type==='relay'?['bedrock_relay_token']:($type==='iam'?['aws_access_key_id','aws_secret_access_key','aws_session_token']:['bedrock_api_key']);foreach($activeSecrets as $k){$v=trim((string)post($k,''));if($v!==''&&!secret_is_masked_input($v))set_secret_setting($k,$v);}flash('success','Amazon Bedrock settings saved securely.');redirect('/admin/ai/');}if($action==='test'){[$ok,$result]=ai_test_connection();$msg=$ok?$result:'Bedrock test failed: '.$result;}if($action==='reset'){foreach(['bedrock_api_key','aws_access_key_id','aws_secret_access_key','aws_session_token','bedrock_relay_token'] as $k)set_setting($k,'');foreach(['bedrock_auth_type'=>'relay','aws_region'=>'us-east-1','bedrock_model_id'=>'openai.gpt-oss-120b','bedrock_api_mode'=>'openai','bedrock_transport'=>'relay','bedrock_endpoint_url'=>'','bedrock_relay_url'=>''] as $k=>$v)set_setting($k,$v);flash('success','AI configuration reset.');redirect('/admin/ai/');}}
$title='Amazon Bedrock'; require __DIR__.'/../includes/header.php';
function admin_secret(string $label,string $name,string $key,string $value):void{?><label><?=e($label)?><div class="secret-control" data-secret-scope="system" data-secret-key="<?=e($key)?>"><input type="password" name="<?=e($name)?>" value="<?=$value!==''?'••••••••':''?>" data-secret-input data-masked="<?=$value!==''?1:0?>" autocomplete="new-password" placeholder="<?=$value!==''?'Saved · enter a new value to replace it':'Enter a value'?>"></div></label><?php }
?>
<div class="ai-page"><div class="page-head"><div><span class="eyebrow">AI SERVICE</span><h1>Amazon Bedrock</h1><p>Choose one connection type. Only the credentials needed by that connection are displayed.</p></div></div><?php if($msg):?><div class="flash info"><?=e($msg)?></div><?php endif;?>
<form class="card form-card wide-form ai-settings-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><h2>Connection</h2><p class="muted">Saved Bedrock credentials are write-only in this interface. The server uses them for provider authentication; they cannot be retrieved by the browser after saving. Enter a new value to rotate a credential.</p><label>Connection Type<select id="adminBedrockConnection" name="connection_type"><option value="api_key" <?=$connectionType==='api_key'?'selected':''?>>OpenAI-Compatible Base + API Key</option><option value="iam" <?=$connectionType==='iam'?'selected':''?>>AWS IAM Direct</option><option value="relay" <?=$connectionType==='relay'?'selected':''?>>Cloudflare Worker Relay</option></select></label><label>Model ID / Deployment Name<input name="bedrock_model_id" value="<?=e($c['model'])?>" required></label>
<div class="ai-connection-panel" data-connection-panel="api_key"><div class="grid2"><label>Base URL<input name="bedrock_endpoint_url" value="<?=e($c['endpoint'])?>" placeholder="https://bedrock-mantle.us-east-1.api.aws/v1"></label><?php admin_secret('API Key','bedrock_api_key','bedrock_api_key',(string)$c['api_key']);?></div><p class="muted ai-help-text">OpenAI-compatible requests use Base URL + Model ID + API Key.</p></div>
<div class="ai-connection-panel" data-connection-panel="iam" hidden><div class="grid2"><?php admin_secret('AWS Access Key ID','aws_access_key_id','aws_access_key_id',(string)$c['access_key']);admin_secret('AWS Secret Access Key','aws_secret_access_key','aws_secret_access_key',(string)$c['secret_key']);admin_secret('Session Token (optional)','aws_session_token','aws_session_token',(string)$c['session_token']);?><label>AWS Region<input name="aws_region" value="<?=e($c['region'])?>" placeholder="us-east-1" required></label></div><p class="muted ai-help-text">AWS IAM Direct uses SigV4 signing with the credentials above.</p></div>
<div class="ai-connection-panel" data-connection-panel="relay" hidden><div class="grid2"><label>Relay URL<input name="bedrock_relay_url" value="<?=e($c['relay_url'])?>" placeholder="https://your-worker.workers.dev"></label><?php admin_secret('Relay Shared Token','bedrock_relay_token','bedrock_relay_token',(string)$c['relay_token']);?></div><p class="muted ai-help-text">Cloudflare Worker Relay forwards the OpenAI-compatible request and keeps Bedrock credentials off the PHP host.</p><?php require __DIR__.'/../includes/ai-worker-relay-tools.php';?></div><button class="btn" type="submit">Save Configuration</button></form>
<div class="grid2 ai-action-grid" style="margin-top:18px"><form class="card" method="post"><?=csrf_field()?><input type="hidden" name="action" value="test"><button class="btn secondary" type="submit">Test Bedrock Connection</button></form><form class="card" method="post" onsubmit="return confirm('Reset AI configuration?')"><?=csrf_field()?><input type="hidden" name="action" value="reset"><button class="btn danger" type="submit">Reset AI Configuration</button></form></div>
<script>(function(){const s=document.getElementById('adminBedrockConnection'),p=[...document.querySelectorAll('[data-connection-panel]')];function sync(){const type=s?.value||'api_key';p.forEach(x=>{const active=x.dataset.connectionPanel===type;x.hidden=!active;x.querySelectorAll('input,select,textarea,button').forEach(el=>{if(el.type!=='button'&&el.type!=='submit')el.disabled=!active})})}s?.addEventListener('change',sync);sync()})();</script><script defer src="/assets/js/ai-worker-generator.js?v=19.79"></script></div><?php require __DIR__.'/../includes/footer.php'; ?>
